package com.example.editor.recovery;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;

/** AZ backup, restore and drill roots. */
@ConfigurationProperties(prefix="hydra.recovery")
public class HydraRecoveryProperties {
    private Path sourceRoot=Path.of("./data"); private Path storageRoot=Path.of("./data/recovery"); private long maximumBytes=1073741824L; private int maximumFiles=100000; private int maximumBackups=30;
    /** Descripción: Obtiene la información correspondiente a «getSourceRoot» dentro de HydraRecoveryProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Path getSourceRoot(){return sourceRoot;} /** Descripción: Actualiza el estado gestionado por HydraRecoveryProperties mediante la operación «setSourceRoot». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setSourceRoot(Path value){sourceRoot=value;}
    /** Descripción: Obtiene la información correspondiente a «getStorageRoot» dentro de HydraRecoveryProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public Path getStorageRoot(){return storageRoot;} /** Descripción: Actualiza el estado gestionado por HydraRecoveryProperties mediante la operación «setStorageRoot». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setStorageRoot(Path value){storageRoot=value;}
    /** Descripción: Obtiene la información correspondiente a «getMaximumBytes» dentro de HydraRecoveryProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public long getMaximumBytes(){return maximumBytes;} /** Descripción: Actualiza el estado gestionado por HydraRecoveryProperties mediante la operación «setMaximumBytes». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumBytes(long value){maximumBytes=Math.max(1,value);}
    /** Descripción: Obtiene la información correspondiente a «getMaximumFiles» dentro de HydraRecoveryProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumFiles(){return maximumFiles;} /** Descripción: Actualiza el estado gestionado por HydraRecoveryProperties mediante la operación «setMaximumFiles». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumFiles(int value){maximumFiles=Math.max(1,value);}
    /** Descripción: Obtiene la información correspondiente a «getMaximumBackups» dentro de HydraRecoveryProperties. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ public int getMaximumBackups(){return maximumBackups;} /** Descripción: Actualiza el estado gestionado por HydraRecoveryProperties mediante la operación «setMaximumBackups». Entradas: value: valor de entrada que debe procesarse. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ public void setMaximumBackups(int value){maximumBackups=Math.max(1,value);}
}
